import pandas as pd
from pandas import DataFrame
from typing import Dict

def run(inputs: Dict[str, DataFrame]) -> Dict[str, DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark_df = inputs["watermark"]

    # Extract high_ts from watermark
    high_ts = watermark_df["high_ts"].iloc[0]

    # Filter events to only those <= high_ts, sorted by (item_id, event_ts, event_seq)
    events_to_apply = cdc_events[cdc_events["event_ts"] <= high_ts].copy()
    events_to_apply = events_to_apply.sort_values(
        by=["item_id", "event_ts", "event_seq"],
        ascending=True
    ).reset_index(drop=True)

    # Initialize result dict: item_id -> (qty_on_hand, last_event_ts)
    # Start with current snapshot
    snapshot_dict = {}
    if len(target_snapshot) > 0:
        for _, row in target_snapshot.iterrows():
            item_id = row["item_id"]
            snapshot_dict[item_id] = {
                "qty_on_hand": row["qty_on_hand"],
                "last_event_ts": row["last_event_ts"]
            }

    # Apply events sequentially in order
    for _, event in events_to_apply.iterrows():
        event_seq = event["event_seq"]
        event_ts = event["event_ts"]
        op = event["op"]
        item_id = event["item_id"]
        qty = event["qty"]

        if op == "R":  # Receipt: add to qty_on_hand (or start from 0 if new)
            if item_id not in snapshot_dict:
                snapshot_dict[item_id] = {"qty_on_hand": 0, "last_event_ts": event_ts}
            snapshot_dict[item_id]["qty_on_hand"] += qty
            snapshot_dict[item_id]["last_event_ts"] = event_ts

        elif op == "A":  # Adjustment: set qty_on_hand to absolute value
            snapshot_dict[item_id] = {
                "qty_on_hand": qty,
                "last_event_ts": event_ts
            }

        elif op == "D":  # Delist: remove item
            if item_id in snapshot_dict:
                del snapshot_dict[item_id]

    # Reconstruct snapshot DataFrame
    rows = []
    for item_id, data in snapshot_dict.items():
        rows.append({
            "item_id": item_id,
            "qty_on_hand": data["qty_on_hand"],
            "last_event_ts": data["last_event_ts"]
        })

    if rows:
        new_snapshot = pd.DataFrame(rows)
        # Ensure correct dtypes
        new_snapshot["item_id"] = new_snapshot["item_id"].astype("int64")
        new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype("float64")
        new_snapshot["last_event_ts"] = new_snapshot["last_event_ts"].astype("datetime64[us]")
    else:
        new_snapshot = pd.DataFrame({
            "item_id": pd.array([], dtype="int64"),
            "qty_on_hand": pd.array([], dtype="float64"),
            "last_event_ts": pd.array([], dtype="datetime64[us]")
        })

    return {"new_snapshot": new_snapshot}
